  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar) values
('Мединский курс (Том 3)', '3', 'نَائِبُ الْفَاعِلِ (заместитель исполнителя при пассивном глаголе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-subject">نَائِبُ الْفَاعِلِ</span> اسْمٌ مَرْفُوعٌ حُذِفَ فَاعِلُهُ، وَسُبِقَ بِفِعْلٍ مَبْنِيٍّ لِلْمَجْهُولِ.</span><p class="rule-study-text">Заместитель исполнителя следует за пассивным глаголом и стоит в <span class="ar-inline ar-tone-raf" dir="rtl" lang="ar">رَفْعٍ</span>. В исходной активной конструкции он обычно был прямым дополнением.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Активная и пассивная конструкции</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَبْنِيُّ لِلْمَعْلُومِ</span><span class="rule-table-ru">активная конструкция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَبْنِيُّ لِلْمَجْهُولِ</span><span class="rule-table-ru">пассивная конструкция</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُ نَائِبِ الْفَاعِلِ</span><span class="rule-table-ru">разбор заместителя исполнителя</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَهِمَ الطَّالِبُ الدَّرْسَ.</span><span class="rule-table-ru">Студент понял урок.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فُهِمَ الدَّرْسُ.</span><span class="rule-table-ru">Урок был понят.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الدَّرْسُ: نَائِبُ فَاعِلٍ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ.</span><span class="rule-table-ru">«Урок» — заместитель исполнителя в именительном состоянии; признак — дамма.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Основной способ образования</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي: ضُمَّ أَوَّلُهُ، وَكُسِرَ مَا قَبْلَ آخِرِهِ</span><span class="rule-term-ru">В прошедшем глаголе первый знак — дамма, а предпоследний — касра.</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ: ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ</span><span class="rule-term-ru">В настояще-будущем глаголе первый знак — дамма, а предпоследний — фатха.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Прошедшее время: полная таблица шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْلُومُ</span><span class="rule-table-ru">активная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَجْهُولُ</span><span class="rule-table-ru">пассивная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">طَرِيقَةُ التَّحْوِيلِ</span><span class="rule-table-ru">способ преобразования</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السَّبَبُ</span><span class="rule-table-ru">причина особенности</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فَهِمَ</span><span class="rule-table-ru">он понял</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فُهِمَ</span><span class="rule-table-ru">был понят</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَكُسِرَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — касрой.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرُ مَبْدُوءٍ بِتَاءٍ زَائِدَةٍ وَلَا هَمْزَةِ وَصْلٍ.</span><span class="rule-table-ru">Не начинается с добавочной та и соединительной хамзы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَعَدَ</span><span class="rule-table-ru">он обещал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وُعِدَ</span><span class="rule-table-ru">ему было обещано</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَكُسِرَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — касрой.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرُ مَبْدُوءٍ بِتَاءٍ زَائِدَةٍ وَلَا هَمْزَةِ وَصْلٍ.</span><span class="rule-table-ru">Не начинается с добавочной та и соединительной хамзы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نَهَى</span><span class="rule-table-ru">он запретил</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">نُهِيَ</span><span class="rule-table-ru">ему было запрещено</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَكُسِرَ مَا قَبْلَ آخِرِهِ، وَقُلِبَتِ الْأَلِفُ يَاءً.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — касрой; алиф превратился в йа.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">غَيْرُ مَبْدُوءٍ بِتَاءٍ زَائِدَةٍ وَلَا هَمْزَةِ وَصْلٍ.</span><span class="rule-table-ru">Не начинается с добавочной та и соединительной хамзы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَعَلَّمَ</span><span class="rule-table-ru">он учился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُعُلِّمَ</span><span class="rule-table-ru">его обучили</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ وَثَانِيهُ، وَكُسِرَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый и второй знаки стали даммами, предпоследний — касрой.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْدُوءٌ بِتَاءٍ زَائِدَةٍ.</span><span class="rule-table-ru">Начинается с добавочной та.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِسْتَقْبَلَ</span><span class="rule-table-ru">он встретил</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اُسْتُقْبِلَ</span><span class="rule-table-ru">его встретили</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ وَثَالِثُهُ، وَكُسِرَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый и третий знаки стали даммами, предпоследний — касрой.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَبْدُوءٌ بِهَمْزَةِ وَصْلٍ.</span><span class="rule-table-ru">Начинается с соединительной хамзы.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قَالَ، بَاعَ</span><span class="rule-table-ru">он сказал; продал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قِيلَ، بِيعَ</span><span class="rule-table-ru">было сказано; было продано</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قُلِبَتِ الْأَلِفُ يَاءً، وَكُسِرَ أَوَّلُهُ.</span><span class="rule-table-ru">Алиф превратился в йа, первый знак стал касрой.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ الْعَيْنِ.</span><span class="rule-table-ru">Средний корневой согласный — слабый.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَدَّ</span><span class="rule-table-ru">он посчитал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عُدَّ</span><span class="rule-table-ru">был посчитан</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ.</span><span class="rule-table-ru">Первый знак стал даммой.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَعَّفٌ.</span><span class="rule-table-ru">Удвоенный глагол.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Настояще-будущее время: полная таблица шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْلُومُ</span><span class="rule-table-ru">активная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَجْهُولُ</span><span class="rule-table-ru">пассивная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">طَرِيقَةُ التَّحْوِيلِ</span><span class="rule-table-ru">способ преобразования</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">السَّبَبُ</span><span class="rule-table-ru">причина особенности</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَفْهَمُ</span><span class="rule-table-ru">он понимает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُفْهَمُ</span><span class="rule-table-ru">понимается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — фатхой.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حُكْمُ الْفِعْلِ الْمُضَارِعِ.</span><span class="rule-table-ru">Общее правило настояще-будущего глагола.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَعُدُّ</span><span class="rule-table-ru">он считает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُعَدُّ</span><span class="rule-table-ru">считается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — фатхой.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حُكْمُ الْفِعْلِ الْمُضَارِعِ.</span><span class="rule-table-ru">Общее правило настояще-будущего глагола.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنْهَى</span><span class="rule-table-ru">он запрещает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُنْهَى</span><span class="rule-table-ru">запрещается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — фатхой.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حُكْمُ الْفِعْلِ الْمُضَارِعِ.</span><span class="rule-table-ru">Общее правило настояще-будущего глагола.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَتَعَلَّمُ</span><span class="rule-table-ru">он учится</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُتَعَلَّمُ</span><span class="rule-table-ru">изучается</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — фатхой.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حُكْمُ الْفِعْلِ الْمُضَارِعِ.</span><span class="rule-table-ru">Общее правило настояще-будущего глагола.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَسْتَقْبِلُ</span><span class="rule-table-ru">он встречает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُسْتَقْبَلُ</span><span class="rule-table-ru">его встречают</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — фатхой.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حُكْمُ الْفِعْلِ الْمُضَارِعِ.</span><span class="rule-table-ru">Общее правило настояще-будущего глагола.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَقُولُ، يَبِيعُ</span><span class="rule-table-ru">он говорит; продаёт</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُقَالُ، يُبَاعُ</span><span class="rule-table-ru">говорится; продаётся</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَقُلِبَ حَرْفُ الْعِلَّةِ أَلِفًا.</span><span class="rule-table-ru">Первый знак стал даммой, слабая буква превратилась в алиф.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ الْعَيْنِ.</span><span class="rule-table-ru">Средний корневой согласный — слабый.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَعِدُ</span><span class="rule-table-ru">он обещает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُوعَدُ</span><span class="rule-table-ru">ему обещают</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ضُمَّ أَوَّلُهُ، وَفُتِحَ مَا قَبْلَ آخِرِهِ، وَرُدَّ حَرْفُ الْعِلَّةِ الْمَحْذُوفُ.</span><span class="rule-table-ru">Первый знак стал даммой, предпоследний — фатхой; удалённая слабая буква восстановлена.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُعْتَلُّ الْفَاءِ.</span><span class="rule-table-ru">Первый корневой согласный — слабый.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пассив без переходного дополнения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا يَأْتِي مَعَ الْفِعْلِ اللَّازِمِ</span><span class="rule-table-ru">что сопровождает непереходный глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">الْجَارُّ وَالْمَجْرُورُ</span><span class="rule-table-ru">предлог с управляемым именем</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ذُهِبَ إِلَيْهِ.</span><span class="rule-table-ru">К нему пошли.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الظَّرْفُ</span><span class="rule-table-ru">обстоятельственное имя</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سِيرَ يَوْمُ الْجُمُعَةِ.</span><span class="rule-table-ru">В пятницу шли.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جُلِسَ جُلُوسٌ حَسَنٌ.</span><span class="rule-table-ru">Сидели хорошим сидением.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Каким бывает заместитель исполнителя</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صُورَتُهُ</span><span class="rule-table-ru">его форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">его синтаксический статус</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمٌ ظَاهِرٌ</span><span class="rule-table-ru">явно выраженное имя</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلَ الْمُدَرِّسُ.</span><span class="rule-table-ru">Преподавателя спросили.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الْمُدَرِّسُ نَائِبُ فَاعِلٍ مَرْفُوعٌ.</span><span class="rule-table-ru">«Преподаватель» — заместитель исполнителя в именительном состоянии.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمِيرٌ ظَاهِرٌ</span><span class="rule-table-ru">явно выраженное местоимение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْتُ، سُئِلْتَ، سُئِلْتِ، سُئِلْتُمْ، سُئِلْتُنَّ، سُئِلُوا، سُئِلْنَ، سُئِلْنَا، تُسْأَلِينَ</span><span class="rule-table-ru">все явно выраженные местоименные формы приведены в отдельной таблице ниже</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِي مَحَلِّ رَفْعٍ نَائِبُ فَاعِلٍ.</span><span class="rule-table-ru">занимает позицию именительного состояния как заместитель исполнителя</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمِيرٌ مُسْتَتِرٌ</span><span class="rule-table-ru">скрытое местоимение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلَتْ؛ تَقْدِيرُهُ هِيَ. تُسْأَلُ؛ تَقْدِيرُهُ أَنْتَ أَوْ هِيَ.</span><span class="rule-table-ru">Её спросили — подразумевается «она»; тебя/её спрашивают — подразумевается «ты» или «она».</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِي مَحَلِّ رَفْعٍ نَائِبُ فَاعِلٍ.</span><span class="rule-table-ru">занимает позицию именительного состояния как заместитель исполнителя</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все явно выраженные местоименные формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الضَّمِيرُ فِي مَحَلِّ رَفْعٍ</span><span class="rule-table-ru">местоименный признак в позиции именительного состояния</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْتُ</span><span class="rule-table-ru">меня спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا</span><span class="rule-table-ru">я</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّاءُ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">подвижная та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْتَ</span><span class="rule-table-ru">тебя, мужчину, спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتَ</span><span class="rule-table-ru">ты, мужчина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّاءُ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">подвижная та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْتِ</span><span class="rule-table-ru">тебя, женщину, спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتِ</span><span class="rule-table-ru">ты, женщина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّاءُ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">подвижная та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْتُمْ</span><span class="rule-table-ru">вас, мужчин, спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتُمْ</span><span class="rule-table-ru">вы, мужчины</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّاءُ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">подвижная та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْتُنَّ</span><span class="rule-table-ru">вас, женщин, спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتُنَّ</span><span class="rule-table-ru">вы, женщины</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّاءُ الْمُتَحَرِّكَةُ</span><span class="rule-table-ru">подвижная та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلُوا</span><span class="rule-table-ru">их, мужчин, спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُمْ</span><span class="rule-table-ru">они, мужчины</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ</span><span class="rule-table-ru">вау мужского множественного</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْنَ</span><span class="rule-table-ru">их, женщин, спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هُنَّ</span><span class="rule-table-ru">они, женщины</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نُونُ النِّسْوَةِ</span><span class="rule-table-ru">нун женского множественного</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">سُئِلْنَا</span><span class="rule-table-ru">нас спросили</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَحْنُ</span><span class="rule-table-ru">мы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَا الْمُتَكَلِّمِينَ</span><span class="rule-table-ru">на говорящих</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تُسْأَلِينَ</span><span class="rule-table-ru">тебя, женщину, спрашивают</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْتِ</span><span class="rule-table-ru">ты, женщина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَاءُ الْمُخَاطَبَةِ</span><span class="rule-table-ru">йа обращения к женщине</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Если глагол управляет несколькими дополнениями</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قَبْلَ الْبِنَاءِ لِلْمَجْهُولِ</span><span class="rule-table-ru">до преобразования в пассив</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَعْدَ الْبِنَاءِ لِلْمَجْهُولِ</span><span class="rule-table-ru">после преобразования в пассив</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ظَنَّ مُحَمَّدٌ الْمُدَرِّسَ غَائِبًا.</span><span class="rule-table-ru">Мухаммад считал преподавателя отсутствующим.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">ظُنَّ الْمُدَرِّسُ غَائِبًا.</span><span class="rule-table-ru">Преподавателя сочли отсутствующим.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ الْأَوَّلُ نَائِبُ فَاعِلٍ، وَالْمَفْعُولُ الثَّانِي مَنْصُوبٌ.</span><span class="rule-table-ru">Первое дополнение становится заместителем исполнителя, второе остаётся в винительном состоянии.</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'После удаления исполнителя прямое дополнение занимает его место и становится именем в именительном состоянии; шарх подробно показывает образование пассивных форм.', 'نَائِبُ الْفَاعِلِ هُوَ الاِسْمُ الْمَرْفُوعُ الَّذِي حُذِفَ فَاعِلُهُ، وَسُبِقَ بِفِعْلٍ مَبْنِيٍّ لِلْمَجْهُولِ. وَهُوَ فِي الْأَصْلِ مَفْعُولٌ بِهِ. يُضَمُّ أَوَّلُ الْفِعْلِ الْمَاضِي وَيُكْسَرُ مَا قَبْلَ آخِرِهِ، وَيُضَمُّ أَوَّلُ الْفِعْلِ الْمُضَارِعِ وَيُفْتَحُ مَا قَبْلَ آخِرِهِ.'),
('Мединский курс (Том 3)', '3', 'النَّسَبُ (образование относительного имени)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">النَّسَبُ</span> إِلْحَاقُ يَاءٍ مُشَدَّدَةٍ فِي آخِرِ الاِسْمِ، وَكَسْرُ مَا قَبْلَهَا، لِلدَّلَالَةِ عَلَى نِسْبَتِهِ.</span><p class="rule-study-text">К концу имени добавляется усиленная йа, а предыдущая буква получает касру; новая форма указывает на отношение к исходному имени.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الاِسْمُ</span><span class="rule-table-ru">исходное имя</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَنْسُوبُ</span><span class="rule-table-ru">относительная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْهِنْدُ</span><span class="rule-table-ru">Индия</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">هِنْدِيٌّ</span><span class="rule-table-ru">индийский</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْسُوبٌ إِلَى الْهِنْدِ</span><span class="rule-table-ru">относящийся к Индии</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعِرَاقُ</span><span class="rule-table-ru">Ирак</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِرَاقِيٌّ</span><span class="rule-table-ru">иракский</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْسُوبٌ إِلَى الْعِرَاقِ</span><span class="rule-table-ru">относящийся к Ираку</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّحْوُ</span><span class="rule-table-ru">грамматика</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَحْوِيٌّ</span><span class="rule-table-ru">грамматический</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْسُوبٌ إِلَى النَّحْوِ</span><span class="rule-table-ru">относящийся к грамматике</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّارِيخُ</span><span class="rule-table-ru">история</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَارِيخِيٌّ</span><span class="rule-table-ru">исторический</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْسُوبٌ إِلَى التَّارِيخِ</span><span class="rule-table-ru">относящийся к истории</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّبِيُّ</span><span class="rule-table-ru">пророк</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَبَوِيٌّ</span><span class="rule-table-ru">пророческий</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْسُوبٌ إِلَى النَّبِيِّ</span><span class="rule-table-ru">относящийся к пророку</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَخُ</span><span class="rule-table-ru">брат</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَخَوِيٌّ</span><span class="rule-table-ru">братский</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَنْسُوبٌ إِلَى الْأَخِ</span><span class="rule-table-ru">относящийся к брату</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два особых случая</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْقَاعِدَةُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَخْتُومٌ بِيَاءٍ مُشَدَّدَةٍ</span><span class="rule-table-ru">слово оканчивается усиленной йа</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُحْذَفُ الْيَاءُ، وَتَحِلُّ مَحَلَّهَا يَاءُ النَّسَبِ.</span><span class="rule-table-ru">Исходная йа удаляется, а её место занимает йа относительного имени.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ نَبِيٌّ، وَالنَّسَبُ نَبَوِيٌّ.</span><span class="rule-table-ru">исходное слово «пророк», относительная форма «пророческий»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَحْذُوفُ اللَّامِ</span><span class="rule-table-ru">удалён третий корневой согласный</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَجِبُ رَدُّ الْمَحْذُوفِ فِي النَّسَبِ.</span><span class="rule-table-ru">В относительной форме удалённый согласный обязательно восстанавливается.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ أَخٌ وَأَبٌ، وَالنَّسَبُ أَخَوِيٌّ وَأَبَوِيٌّ.</span><span class="rule-table-ru">исходные слова «брат» и «отец»; относительные формы «братский» и «отцовский»</span></td></tr></tbody></table></div></div></div>', 2, 'rule', 'Относительное имя образуется добавлением усиленной йа после касры; шарх отдельно объясняет слова с исходной усиленной йа и с удалённым третьим корневым согласным.', 'النَّسَبُ هُوَ إِلْحَاقُ يَاءٍ مُشَدَّدَةٍ فِي آخِرِ الاِسْمِ، وَكَسْرُ مَا قَبْلَهَا، لِلدَّلَالَةِ عَلَى نِسْبَتِهِ. وَإِذَا كَانَتِ الْكَلِمَةُ مَخْتُومَةً بِيَاءٍ مُشَدَّدَةٍ حُذِفَتْ وَحَلَّتْ مَحَلَّهَا يَاءُ النَّسَبِ، وَإِذَا كَانَتْ لَامُ الْكَلِمَةِ مَحْذُوفَةً وَجَبَ رَدُّهَا.'),
('Мединский курс (Том 3)', '3', 'إِمَّا وَإِمَّا (парная частица «либо… либо…»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">إِمَّا</span> حَرْفٌ يُفِيدُ خَمْسَةَ مَعَانٍ: التَّفْصِيلَ، وَالشَّكَّ، وَالتَّخْيِيرَ، وَالْإِبَاحَةَ، وَالْإِبْهَامَ.</span><p class="rule-study-text">Шарх приводит пять употреблений парной частицы «либо… либо…».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Пять значений и все примеры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и русский перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّفْصِيلُ</span><span class="rule-table-ru">разделение по видам</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الاِسْمُ إِمَّا مُذَكَّرٌ، وَإِمَّا مُؤَنَّثٌ.</span><span class="rule-table-ru">Имя бывает либо мужского рода, либо женского.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّكُّ</span><span class="rule-table-ru">сомнение</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِبْرَاهِيمُ إِمَّا مَرِيضٌ، وَإِمَّا مُسَافِرٌ.</span><span class="rule-table-ru">Ибрахим либо болен, либо находится в поездке.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّخْيِيرُ</span><span class="rule-table-ru">выбор</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِمَّا أَنْ تَزُورَنِي، وَإِمَّا أَنْ أَزُورَكَ.</span><span class="rule-table-ru">Либо ты навестишь меня, либо я навещу тебя.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِبَاحَةُ</span><span class="rule-table-ru">дозволение</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَعَلَّمْ إِمَّا فِقْهًا، وَإِمَّا نَحْوًا.</span><span class="rule-table-ru">Изучай либо фикх, либо грамматику.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِبْهَامُ</span><span class="rule-table-ru">неопределённость</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْعُصَاةُ إِمَّا يُعَذِّبُهُمُ اللَّهُ، وَإِمَّا يَتُوبُ عَلَيْهِمْ.</span><span class="rule-table-ru">Грешников Аллах либо накажет, либо примет их покаяние.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Предложение для разбора</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">الاِسْمُ إِمَّا مُذَكَّرٌ، وَإِمَّا مُؤَنَّثٌ.</span><span class="rule-example-ru">Имя бывает либо мужского рода, либо женского.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الاِسْمُ</span><span class="rule-table-ru">имя</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">подлежащее именного предложения в именительном состоянии; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">подлежащее именного предложения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِمَّا</span><span class="rule-table-ru">либо</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ تَفْصِيلٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица разделения, построенная на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ تَفْصِيلٍ</span><span class="rule-table-ru">частица разделения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُذَكَّرٌ</span><span class="rule-table-ru">мужской род</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">خَبَرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">сказуемое в именительном состоянии; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-table-ru">сказуемое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْوَاوُ</span><span class="rule-table-ru">вау</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">сочинительная частица, построенная на фатхе, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ عَطْفٍ</span><span class="rule-table-ru">сочинительная частица</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِمَّا</span><span class="rule-table-ru">либо</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ تَفْصِيلٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">частица разделения, построенная на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ تَفْصِيلٍ</span><span class="rule-table-ru">частица разделения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُؤَنَّثٌ</span><span class="rule-table-ru">женский род</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مَعْطُوفٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">сочинённое слово в именительном состоянии; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعْطُوفٌ</span><span class="rule-table-ru">сочинённое слово</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'В зависимости от контекста парная إِمَّا выражает разделение, сомнение, выбор, дозволение либо неопределённость.', 'إِمَّا حَرْفٌ يُفِيدُ التَّفْصِيلَ، أَوِ الشَّكَّ، أَوِ التَّخْيِيرَ، أَوِ الْإِبَاحَةَ، أَوِ الْإِبْهَامَ. وَهُوَ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.'),
('Мединский курс (Том 3)', '3', 'ثَلَاثُمِائَةٌ وَأَخَوَاتُهَا (числительные от трёхсот до девятисот)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">ثَلَاثُمِائَةٌ</span> وَأَخَوَاتُهَا تَتَكَوَّنُ مِنْ لَفْظَيْنِ: الْأَوَّلُ يُعْرَبُ بِحَسَبِ الْعَامِلِ، وَ<span class="ar-tone-jarr">مِائَةٌ</span> مَجْرُورَةٌ دَائِمًا بِالْإِضَافَةِ.</span><p class="rule-study-text">Первая часть числительного принимает падежное состояние по своей роли, а «сто» всегда стоит как вторая часть идафы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Диапазон форм</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">ثَلَاثُمِائَةٌ</span><span class="rule-term-ru">триста</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">أَرْبَعُمِائَةٌ</span><span class="rule-term-ru">четыреста</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">تِسْعُمِائَةٌ</span><span class="rule-term-ru">девятьсот</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Первое предложение для разбора</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">عِنْدِي ثَلَاثُمِائَةِ رِيَالٍ.</span><span class="rule-example-ru">У меня триста риялов.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب первого предложения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُزْءُ</span><span class="rule-table-ru">часть</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عِنْدِي</span><span class="rule-table-ru">у меня</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">شِبْهُ الْجُمْلَةِ فِي مَحَلِّ رَفْعٍ خَبَرٌ مُقَدَّمٌ.</span><span class="rule-table-ru">оборот занимает позицию именительного состояния как предшествующее сказуемое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مُقَدَّمٌ</span><span class="rule-table-ru">предшествующее сказуемое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ثَلَاثُ</span><span class="rule-table-ru">три</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُبْتَدَأٌ مُؤَخَّرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ.</span><span class="rule-table-ru">последующее подлежащее в именительном состоянии; признак — явная дамма; первая часть идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يُعْرَبُ بِحَسَبِ الْعَامِلِ.</span><span class="rule-table-ru">изменяется по управляющему фактору</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مِائَةِ</span><span class="rule-table-ru">сто</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ.</span><span class="rule-table-ru">вторая часть идафы в родительном состоянии; признак — явная касра; одновременно первая часть следующей идафы</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَجْرُورَةٌ دَائِمًا بِالْإِضَافَةِ.</span><span class="rule-table-ru">всегда стоит в родительном состоянии из-за идафы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">رِيَالٍ</span><span class="rule-table-ru">риял</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">вторая часть идафы в родительном состоянии; признак — явная касра</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْدُودُ</span><span class="rule-table-ru">считаемое имя</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Второе предложение для разбора</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أُرِيدُ أَرْبَعَمِائَةِ رِيَالٍ.</span><span class="rule-example-ru">Я хочу четыреста риялов.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب второго предложения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجُزْءُ</span><span class="rule-table-ru">часть</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهُ</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أُرِيدُ</span><span class="rule-table-ru">я хочу</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ أَنَا.</span><span class="rule-table-ru">настояще-будущий глагол в именительном состоянии; признак — явная дамма; исполнитель — скрытое местоимение «я»</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ وَفَاعِلٌ مُسْتَتِرٌ</span><span class="rule-table-ru">глагол и скрытый исполнитель</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَرْبَعَ</span><span class="rule-table-ru">четыре</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ.</span><span class="rule-table-ru">прямое дополнение в винительном состоянии; признак — явная фатха; первая часть идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يُعْرَبُ بِحَسَبِ الْعَامِلِ.</span><span class="rule-table-ru">изменяется по управляющему фактору</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مِائَةِ</span><span class="rule-table-ru">сто</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ.</span><span class="rule-table-ru">вторая часть идафы в родительном состоянии; признак — явная касра; одновременно первая часть следующей идафы</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَجْرُورَةٌ دَائِمًا بِالْإِضَافَةِ.</span><span class="rule-table-ru">всегда стоит в родительном состоянии из-за идафы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">رِيَالٍ</span><span class="rule-table-ru">риял</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">вторая часть идафы в родительном состоянии; признак — явная касра</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْدُودُ</span><span class="rule-table-ru">считаемое имя</span></td></tr></tbody></table></div></div></div>', 4, 'rule', 'В числительных 300–900 первая часть изменяется по управляющему фактору, а مِائَةٌ всегда является второй частью идафы в родительном состоянии.', 'ثَلَاثُمِائَةٌ وَأَخَوَاتُهَا مِنْ أَرْبَعُمِائَةٍ إِلَى تِسْعِمِائَةٍ تَتَكَوَّنُ مِنْ لَفْظَيْنِ: الْأَوَّلُ يُعْرَبُ بِحَسَبِ الْعَامِلِ، وَالثَّانِي مِائَةٌ وَيَكُونُ دَائِمًا مَجْرُورًا بِالْإِضَافَةِ.'),
('Мединский курс (Том 3)', '3', 'اسْمُ الْجِنْسِ الْجَمْعِيُّ (собирательное родовое имя)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">اسْمُ الْجِنْسِ الْجَمْعِيُّ</span> يَكُونُ الْفَرْقُ بَيْنَهُ وَبَيْنَ مُفْرَدِهِ الْيَاءَ أَوِ التَّاءَ.</span><p class="rule-study-text">Единичная форма отличается от собирательной либо йа, либо та.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Различие посредством йа</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ</span><span class="rule-table-ru">собирательная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">единичная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رُومٌ</span><span class="rule-table-ru">римляне</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">رُومِيٌّ</span><span class="rule-table-ru">римлянин</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَرْقُ بِالْيَاءِ</span><span class="rule-table-ru">различительный признак — йа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُرْكٌ</span><span class="rule-table-ru">турки</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُرْكِيٌّ</span><span class="rule-table-ru">турок</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَرْقُ الْيَاءُ</span><span class="rule-table-ru">различительный признак — йа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عَرَبٌ</span><span class="rule-table-ru">арабы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عَرَبِيٌّ</span><span class="rule-table-ru">араб</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَرْقُ الْيَاءُ</span><span class="rule-table-ru">различительный признак — йа</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Различие посредством та</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ</span><span class="rule-table-ru">собирательная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">единичная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَمَكٌ</span><span class="rule-table-ru">рыба как вид</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">سَمَكَةٌ</span><span class="rule-table-ru">одна рыба</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَرْقُ بِالتَّاءِ</span><span class="rule-table-ru">различительный признак — та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَقَرٌ</span><span class="rule-table-ru">крупный рогатый скот</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَقَرَةٌ</span><span class="rule-table-ru">одна корова</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْفَرْقُ التَّاءُ</span><span class="rule-table-ru">различительный признак — та</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حَبٌّ</span><span class="rule-table-ru">зерно как вид</span></td><td><span 