insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'نَائِبُ الْفَاعِلِ
نائبُ الفاعلِ ، هو : الاسمُ المرفوعُ الذي حُذِف فاعلُه ، ويُسْبَقُ بفعلٍ مَبْنِيًّ لِلْمَجْهُولِ .
صِيَاغَةُ الفعل المبني للمجهول : إذا كان الفعل ماضياً ( ضُمَّ أَوَّلُه وكُسِرَ ما قبلَ آخره ) .
وإذا كان مضارعاً ( ضُمَّ أوّله وفُتِحَ ما قبل آخره ) .
نائب الفاعل في الأصل مفعول به حُذف فاعله بعد بناء الفعل للمجهول ، نحو :
فَهِمَ الطالبُ الدرسَ          فُهِمَ الدرسُ : نائب فاعل مرفوع وعلامة رفعه الضمة .
والفاعل ، هو: الاسم المرفوع الذي يُسْبَق بفعل مبنيّ للمعلوم ، نحو: فَهِمَ الطالبُ الدرسَ.
* جدولٌ يُبَيَّنُ الفعلَ المبنيَّ للمعلومِ ، وطريقةَ تحويلهِ إلى مبنيٍّ للمجهولِ :
