لأنه معتل الفاء .
* لا يُبْنَى الفعلُ اللاَّزمُ للمجهول إلا مع الجارّ والمجرور ، أو الظَّرف، أو المصدر ، نحو :
ذُهِبَ إليه . سِيَر يومُ الجمعةِ . جُلِسَ جُلُوسٌ حَسَنٌ .
* قد يكون اسمُ الفاعل اسماً ظاهراً ، نحو : سُئِلَ المدرَّسُ .
وقد يكون ضميراً ظاهراً ، نحو : سُئِلْتُ . سُئِلْتَ . سُئِلْتِ . سُئِلْتُمْ . سُئِلْتُنَّ . سُئِلُوا . سُئِلْنَ . سُئِلْنَا . وتُسْأَلِينَ . فالتاء المتحرَّكَة، وواو الجماعة ، ونون النَّسوة ، ونا المتكلَّمين ، وياء الْمُخاطَبة: في محل رفع نائب فاعل .
وقد يكون ضميراً مستتراً ، نحو : سُئِلَتْ : نائب الفاعل ضمير مستتر تقديره ( هي ) .
ونحو : تُسْأَلُ : نائب الفاعل ضمير مستتر تقديره ( أنتَ ، أو هي ) .
* إذا كان الفعلُ مُتَعَدَّياً إلى أكثر من مفعول ، ثم بُنِيَ للمجهول يكون المفعول الأَوَّل هو النَّائب عن الفاعل ، ويَبقى المفعول الثاني منصوباً ، نحو :
ظنَّ محمدٌ المدرسَ غائباً              ظُنَّ المدرسُ غائباً .', 22, 24, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '3' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'النَّسَبُ
النَّسَبُ ، هو : إِلْحَاقُ ياءٍ مُشَدَّدَةٍ في آخِرِ الاسمِ ،مكسورٌ ما قبلها لِتَدُلَّ على نِسْبَتِهِ ،نحو:
الهِنْدُ : هِنْدِيٌّ . العِرَاقُ : عِرَاقِيٌّ . النَّحْوُ : نَحْوِيٌّ . التَّارِيخُ : تَارِيخِيٌّ . النَّبِيُّ : نَبَوِيٌّ . الأَخُ : أَخَوِيٌّ .
* إذا كانت الكلمة مختومة بياء مُشَدَّدَة ، نحو ( نَبِيٌّ ) حُذِفت هذه الياء ، وَحلَّتْ مَحلَّها ياء النَّسَب .
إذا كانت الكلمة محذوفة اللاَّم ، نحو (أَخٌ ، وأَبٌ) وَجَبَ رَدُّ المحذوف في النَّسَب ؛ فتقول: أَخَوِيٌّ ، وأَبَوِيٌّ .', 24, 24, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '3' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'إِمَّا ، وَإِمَّا
إِمَّا : حرفٌ يُفِيدُ عِدَّةَ أُمورٍ :
1- التَّفْصِيل ، نحو : الاسم إمَّا مُذكَّرٌ ، وإِمَّا مُؤَنَّثٌ .
2- الشَّكّ ، نحو : إبراهيمُ إمَّا مريضٌ ، وإمَّا مُسافرٌ .
3- التَّخْيِير ، نحو : إمَّا أَنْ تزورَني ، وإمَّا أَنْ أزورَك .
4- الإِبَاحَة ، نحو : تَعَلَّمْ إمَّا فِقْهاً ، وإمَّا نَحْواً .
5- الإبْهَام ، نحو : العُصَاةُ إمَّا يُعَذَّبُهم اللهُ ، وإمَّا يتوبُ عليهم .
الإعراب : الاسمُ إمَّا مذكَّرٌ ، وإمَّا مؤنثٌ
الاسم : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة .
إِمَّا : حرف تفصيل مبني على السكون لا محلّ له من الإعراب .
مُذكَّر : خبر مرفوع وعلامة رفعه الضمة الظاهرة .
الواو : حرف عطف مبني على الفتح لا محلَّ له من الإعراب .
إِمَّا : حرف تفصيل مبني على السكون لا محل له من الإعراب .
مُؤنَّث : معطوف مرفوع وعلامة رفعه الضمة الظاهرة .', 24, 25, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '3' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'ثَلاَثُمِائَةٍ
ثَلاَثُمِائةٍ وأخواتُها ، أَرْبَعُمِائةٍ ... حَتَّى تِسْعِمِائَةٍ : تتكون من لفظين ،
الأوَّل  : ثلاث ، وهذه تعربُ بِحَسَبِ العَامل .
والثاني : مِائة ، وهذه تُعربُ دائماً مجرورةً بالإضافة .
الإعراب :
عندي ثَلاثُمِائَةِ ريالٍ :
عندي : شبه الجملة خبر مقدم في محل رفع .
ثلاثُ : مبتدأ مُؤخَّر مرفوع وعلامة رفعه الضمة الظاهرة ، وهو مضاف .
مائة : مضاف إليه مجرور وعلامة جرَّه الكسرة الظاهرة ، وهو مضاف .
ريالٍ : مضاف إليه مجرور وعلامة جرَّه الكسرة الظاهرة .
* أريدُ أَرْبَعَمِائَةِ ريالٍ :
أريدُ : فعل مضارع مرفوع وعلامة رفعه الضمة الظاهرة ، والفاعل ضمير مستتر
تقديره ( أنا ) .
أربعَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة ، وهو مضاف
مائةِ : مضاف إليه مجرور وعلامة جره الكسرة الظاهرة ، وهو مضاف
ريالٍ : مضاف إليه مجرور وعلامة جره الكسرة الظاهرة .', 25, 26, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '3' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'اسمُ الجِنْسِ الْجَمْعِيَّ
اسمُ الجنسِ الجمعيَّ ، هو : الذي يكونُ الفَرْقُ بينه وبين مُفْرَدِه الياء ، أو التَّاء .
الأمثلة :
( 1 ) رُومٌ : رُومِيٌّ .          تُرْكٌ : تُرْكِيٌّ .       عَرَبٌ : عَرَبِيٌّ .
( 2 ) سَمَكٌ : سَمَكَةٌ .        بَقَرٌ : بَقَرَةٌ .         حَبٌّ : حَبَّةٌ .
لاَحِظ : الفرقُ بين الجمع ، والمفرد في المجموعة الأولى (الياء) والفرق بين الجمع ، والمفرد في المجموعة الثانية ( التاء ) .', 26, 26, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '3' and sort_order = 5;
  select count(*) into new_rule_count from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '3';
  select count(*) into source_count from public.rule_sources rs join public.rules r on r.id = rs.rule_id where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '3';
  if new_rule_count <> 5 or source_count <> 5 then raise exception 'Book 3 lesson 3 verification failed: rules %, sources %', new_rule_count, source_count; end if;
end
$migration$;
commit;
